{"conversation":"Ok, let me try to count for each song the remainder when divided by 60, and then check pairs whose remainders add up to 60.","python_code":"from typing import List

class Solution:
    def numPairsDivisibleBy60(self, time: List[int]) -> int:
        remainder_counts = [0] * 60
        count = 0
        for t in time:
            remainder = t % 60
            # I think pairs with remainder 0 need special handling
            if remainder == 0:
                count += remainder_counts[0]
            else:
                count += remainder_counts[60 - remainder]
            remainder_counts[remainder] += 1
        return count
"}
